prompt_extraction.bloc_schema_specifique:
"caracteristiques_mission_moe": {
  "typologie": "MOE complète, MOE partielle, BET structure, BET fluides, étude d'impact, AMO technique",
  "phases_couvertes": ["ESQ", "APS", "APD", "PRO", "DCE", "ACT", "EXE", "OPC", "AOR"],
  "typologie_ouvrage": "Type d'ouvrage projet (bâtiment public, ouvrage d'art, lotissement, etc.)",
  "montant_travaux_estime": null,
  "complexite_technique": "standard, complexe, expert",
  "livrables_par_phase": [
    {
      "phase": "Ex: 'DIAG', 'ESQ', 'APS', 'APD', 'PRO', 'ACT', 'EXE', 'AOR'",
      "livrables": ["Liste des livrables détaillés attendus pour cette phase"]
    }
  ],
  "taux_remuneration_moe_pct": "Honoraires MOE en % du montant travaux (typique 8-15% selon complexité, peut atteindre 18-20% pour ouvrages d'art ou rénovation patrimoine). null si non précisé dans CCAP/RC.",
  "indices_revision": ["BT01, FFB, IPC, ING — recopie les indices mentionnés dans CCAP pour la révision des prix"],
  "coordinations_associees": ["Coordinations incluses ou exclues du marché : 'OPC inclus', 'SPS hors marché', 'SSI inclus', 'AMO PRO exclu'. Liste vide si non précisé."],
  "organigramme_attendu": [
    {
      "profil": "Ex: 'Chef de projet MOE', 'Ingénieur structures béton précontraint', 'Économiste construction', 'Dessinateur projeteur'",
      "nombre": null,
      "anciennete_min_annees": null
    }
  ],
  "bim_niveau": "Niveau BIM attendu (ex: 'LOD 300', 'LOD 400 IFC', 'maturité niveau 2', 'BIM Management interne uniquement'). null si BIM non requis."
},
"qualifications_moe": {
  "opqibi": ["Liste des qualifications OPQIBI exigées — codes à 4 chiffres (ex: \"1201\", \"1106\"). Liste vide si aucune."],
  "opqcm": ["Qualifications OPQCM exigées le cas échéant (management de projet). Liste vide sinon."],
  "bim": null,
  "autres": []
}

